function luxuryAvailableFrom(item) {
    const d = new Date();
    d.setDate(d.getDate() + 1);
    const [h] = item.startsAt.split(':').map(Number);
    const months = [
        'Jan',
        'Feb',
        'Mar',
        'Apr',
        'May',
        'Jun',
        'Jul',
        'Aug',
        'Sep',
        'Oct',
        'Nov',
        'Dec'
    ];
    return `${d.getDate()} ${months[d.getMonth()]}, ${(h + 11) % 12 + 1} ${h < 12 ? 'AM' : 'PM'}`;
}
