const dayIso = (d)=>`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
function groupDepartureDates(trip) {
    return trip.departures.map(({ in: days, seats })=>{
        const d = new Date();
        d.setDate(d.getDate() + days);
        return {
            date: dayIso(d),
            seats
        };
    });
}
