function packageDepartures(count = 8) {
    const out = [];
    const d = new Date();
    d.setDate(d.getDate() + 7);
    while(out.length < count){
        if (d.getDay() === 6) {
            out.push(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`);
        }
        d.setDate(d.getDate() + 1);
    }
    return out;
}
